#!/usr/bin/env bash
set -euo pipefail
mkdir -p /workspace/gpu-worker
cd /workspace/gpu-worker
base64 -d <<'B64' | tar -xzf -

B64
python3 -m venv .venv
source .venv/bin/activate
pip install -r requirements.txt
export GPU_API_KEY="${GPU_API_KEY:-$(openssl rand -hex 24)}"
export GPU_WEBHOOK_SECRET="${GPU_WEBHOOK_SECRET:-$(openssl rand -hex 32)}"
echo "GPU_API_KEY=$GPU_API_KEY"
echo "GPU_WEBHOOK_SECRET=$GPU_WEBHOOK_SECRET"
echo "Files ready in /workspace/gpu-worker"
echo "Next: start tunnel, set WORKER_PUBLIC_URL, then:"
echo "  source /workspace/gpu-worker/.venv/bin/activate"
echo "  cd /workspace/gpu-worker && uvicorn main:app --host 127.0.0.1 --port 8081"
